# Generated by build.py from recipe.yml for recipe smtp-serve-two-mail-domains. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'one.eml'), "From: noreply@one.test`nTo: ann@one.test`nSubject: Welcome to One`n`nThanks for joining One.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'two.eml'), "From: noreply@two.test`nTo: ann@two.test`nSubject: Welcome to Two`n`nThanks for joining Two.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'wait-log.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh wait-log.sh TEXT LOG. Waits, a second at a time for at most 10, until LOG has a line`n# holding TEXT, then prints those lines without their exchange number.`ntries=0`nuntil grep -q -e `"`$1`" `"`$2`"; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 10 ]; then echo `"no line with `$1 in `$2`" >&2; exit 1; fi`n  sleep 1`ndone`ngrep -e `"`$1`" `"`$2`" | sed 's/^#[0-9]* //' | tr -d '\r'`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'one.test', '--mail-domain', 'two.test', '--mailbox', 'noreply@one.test:onepass', '--mailbox', 'noreply@two.test:twopass', '--mailbox', 'ann@one.test:annone', '--mailbox', 'ann@two.test:anntwo', '--mailbox', 'bo@one.test:boone', '--mailbox', 'bo@two.test:botwo', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --crlf -u noreply@one.test:onepass --mail-from noreply@one.test --mail-rcpt ann@one.test -T one.eml smtp://127.0.0.1:8080/one.test --next -sS --crlf -u noreply@two.test:twopass --mail-from noreply@two.test --mail-rcpt ann@two.test -T two.eml smtp://127.0.0.1:8080/two.test --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@one.test:annone "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)" --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@two.test:anntwo "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)" } finally { Stop-Process $server0 }
